    for (auto& [name, entry] : adapters_) {
        if (entry.handle) {
            llama_adapter_lora_free(entry.handle);
            entry.handle = nullptr;
            ++freed;
        }
        entry.state = AdapterState::COLD;
    }
    adapters_.clear();
    active_name_.clear();
    if (freed > 0) {
        logger->info("Unloaded all {} adapter(s) on shutdown", freed);
    }
}

